void fun(int **p, int n) {
    int *temp = realloc(*p, n * sizeof(int));
    if (temp == NULL) return;
    *p = temp;
    for (int i = 3; i < n; i++) (*p)[i] = (*p)[i - 1] + (*p)[i - 2];
}

int main(void) {
    int *p = malloc(3 * sizeof(int));
    p[0] = 1;
    p[1] = 2;
    p[2] = 3;
    fun(&p, 7);

    int *q = malloc(7 * sizeof(int));
    for (int i = 0; i < 7; i++) q[i] = p[i];
    q[0] = 100;

    int *temp = realloc(q, 9 * sizeof(int));
    if (temp == NULL) {
        free(p);
        free(q);
        return 0;
    }
    q = temp;
    q[7] = p[5] + p[6];
    q[8] = q[7] + p[0];

    printf("%d %d %d %d", p[0], q[0], q[7], q[8]);
    free(p);
    free(q);
}
